package com.tregy.backend.config;
import jakarta.annotation.PostConstruct;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.env.*;import org.springframework.stereotype.Component;
@Component public class ProductionConfigValidator{private final Environment environment;private final String publicUrl;private final String resendKey;private final String from;public ProductionConfigValidator(Environment environment,@Value("${app.public-url}")String publicUrl,@Value("${app.email.resend-api-key:}")String resendKey,@Value("${app.email.from:}")String from){this.environment=environment;this.publicUrl=publicUrl;this.resendKey=resendKey;this.from=from;}@PostConstruct void validate(){if(!environment.acceptsProfiles(Profiles.of("prod")))return;if(!publicUrl.startsWith("https://"))throw new IllegalStateException("PUBLIC_APP_URL must use HTTPS in prod");if(resendKey.isBlank()||from.isBlank())throw new IllegalStateException("RESEND_API_KEY and EMAIL_FROM are required in prod");}}
